-- ncm_league schema 018: in-game problem reports.
--
-- **The server is the support channel.** A player who hits a gameplay problem should be able to tell NCM from
-- inside NCM, without the owner's Discord, a GitHub account, or the owner being awake. A random visitor can
-- encounter a bug, report it, disconnect and never return -- and the report still has to be there afterwards.
-- That is why this is a row and not a session, a chat message, or a log line.
--
-- **`report_id` is the PRIMARY KEY and is generated by the CLIENT.** That is the whole idempotency design: the
-- page generates one id per attempt and reuses it on retry, the server writes with INSERT IGNORE, and a retry
-- after a timeout is a no-op rather than a duplicate. It also means the acknowledgement can name the id the
-- player's page already knows, so the UI never has to guess whether it worked.
--
-- **No foreign key on `ncm_driver_id`, and it is nullable.** A report from somebody whose identity failed to
-- mint is precisely the report we most want to keep -- that failure is the bug. An FK would refuse exactly the
-- most valuable row, and a driver later removed must not take their evidence with them.
--
-- `context_json` is a bounded snapshot of authoritative facts the systems already knew (ownership, eligibility
-- refusal reason, readiness stage, open panel, position). **Facts, not conclusions:** `eligibility_reason` is
-- recorded, never "ownership bug caused race rejection". The person reading it infers the failure.
--
-- Deliberately absent: status, assignee, priority, replies, and anything else that would make this a ticketing
-- system. There is no conversation here and no queue -- a player submits, NCM captures, the row persists.
NcmSchema = NcmSchema or {}

NcmSchema[#NcmSchema + 1] = {
    version = 18,
    name = "player_report",
    statements = {
        [[CREATE TABLE IF NOT EXISTS player_report (
            report_id CHAR(36) NOT NULL,
            server_id VARCHAR(96) NOT NULL,
            submitted_at BIGINT NOT NULL,
            -- who, as far as we know. All three are nullable: a report from a broken session is still a report.
            ncm_driver_id CHAR(36) NULL,
            user_id VARCHAR(96) NULL,
            player_name VARCHAR(96) NULL,
            -- what the player said, already trimmed and bounded by `player.help.cleanReport`
            player_text VARCHAR(1200) NOT NULL,
            -- what NCM knew at that moment: bounded JSON of facts from authoritative systems
            context_json TEXT NULL,
            build VARCHAR(64) NULL,
            PRIMARY KEY (report_id),
            KEY ix_player_report_time (server_id, submitted_at),
            KEY ix_player_report_driver (ncm_driver_id, submitted_at)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci]],
    },
}
